// PickGauge asset build (Sept 2026).
//
// index.html used to load 30 separate, unminified classic <script> files
// (~975KB) plus 2 stylesheets. This folds them into ONE minified script, ONE
// ES-module script (the Survivor core) and ONE stylesheet, in EXACTLY the old
// load order (scripts/build/manifest.json -- the single source of truth for
// that order). Run with:  scripts/build.sh   (or: node scripts/build/build.mjs)
//
// Design rules (every one has a test in tests/test_bundle_in_sync.mjs):
//  - The source files under app/js, app/data and app/css stay the source of
//    truth and stay loadable/testable on their own. app/dist/* is generated.
//  - Classic scripts share ONE global scope, so each file is minified on its
//    own (esbuild `transform` never renames top-level names in a script) and
//    the results are joined with ";\n". Nothing is wrapped in an IIFE.
//  - A content hash of the manifest + every source file is written into
//    app/dist/build-info.json and into the first line of each output, so a
//    forgotten rebuild is caught by `test_bundle_in_sync.mjs` without needing
//    esbuild installed.
//  - An index source map (sections) maps the minified bundle back to each
//    original file, so DevTools errors show real file names and lines.
//  - Survivor is LAZY (manifest.lazy.survivor): its two classic scripts, its
//    stylesheet and the core ES-module bundle are separate files that
//    pgLoadSurvivor() (app/js/tabs.js) fetches the first time the Survivor tab
//    opens. index.html does not reference them.
import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import { fileURLToPath } from "node:url";
import { createRequire } from "node:module";

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, "..", "..");
const require = createRequire(import.meta.url);
const esbuild = require("esbuild");

const manifestPath = path.join(here, "manifest.json");
const manifest = JSON.parse(fs.readFileSync(manifestPath, "utf8"));
const read = (rel) => fs.readFileSync(path.join(root, rel), "utf8");
const write = (rel, data) => { fs.mkdirSync(path.dirname(path.join(root, rel)), { recursive: true }); fs.writeFileSync(path.join(root, rel), data); };

// ---- content hash (mirrored by tests/test_bundle_in_sync.mjs) ----
const lazyGroups = Object.entries(manifest.lazy || {});
export function allSourceFiles() {
  return [...manifest.js, manifest.module, ...manifest.css, ...lazyGroups.flatMap(([, g]) => [...g.js, ...g.css])];
}
export function sourceHash() {
  const h = crypto.createHash("sha256");
  h.update("manifest\0" + JSON.stringify({ js: manifest.js, module: manifest.module, css: manifest.css, lazy: manifest.lazy || {} }) + "\0");
  for (const f of allSourceFiles()) h.update(f + "\0" + read(f) + "\0");
  // The Survivor core modules are imported by the bridge; include them too.
  const coreDir = path.join(root, "app/survivor-core");
  const walk = (d) => fs.readdirSync(d, { withFileTypes: true }).flatMap((e) => e.isDirectory() ? walk(path.join(d, e.name)) : [path.join(d, e.name)]);
  for (const f of walk(coreDir).filter((p) => p.endsWith(".js")).sort()) h.update(path.relative(root, f) + "\0" + fs.readFileSync(f, "utf8") + "\0");
  return h.digest("hex").slice(0, 16);
}
const hash = sourceHash();

// ---- classic scripts -> minified script(s) + index source map ----
const header = `/*! pickgauge build ${hash} -- generated by scripts/build/build.mjs; edit the files in app/js, app/data, app/css instead */\n`;
function buildClassic(files, outRel) {
  const base = path.basename(outRel);
  let out = header;
  let line = header.split("\n").length - 1;
  const sections = [];
  files.forEach((rel, i) => {
    const r = esbuild.transformSync(read(rel), { minify: true, sourcemap: "external", sourcefile: "/" + rel, legalComments: "none", charset: "utf8" });
    const code = r.code.endsWith("\n") ? r.code : r.code + "\n";
    sections.push({ offset: { line, column: 0 }, map: JSON.parse(r.map) });
    out += code;
    line += code.split("\n").length - 1;
    if (i < files.length - 1) { out += ";\n"; line += 1; }
  });
  out += `//# sourceMappingURL=${base}.map\n`;
  write(outRel, out);
  write(outRel + ".map", JSON.stringify({ version: 3, file: base, sections }));
}
buildClassic(manifest.js, manifest.out.js);
for (const [name, g] of lazyGroups) buildClassic(g.js, manifest.out.lazy[name].js);

// ---- Survivor core (ES modules) -> one module file ----
const mod = esbuild.buildSync({
  entryPoints: [path.join(root, manifest.module)], bundle: true, format: "esm", minify: true, write: false,
  sourcemap: "external", outfile: path.join(root, manifest.out.module), legalComments: "none", charset: "utf8",
});
const modJs = mod.outputFiles.find((f) => f.path.endsWith(".js")).text;
const modMap = mod.outputFiles.find((f) => f.path.endsWith(".map")).text;
write(manifest.out.module, header + modJs.replace(/\n\/\/# sourceMappingURL=.*\n?$/, "\n") + "//# sourceMappingURL=survivor-core.min.js.map\n");
// The header line shifts every generated line by one; prefix the mappings.
const mm = JSON.parse(modMap); mm.mappings = ";" + mm.mappings; mm.file = "survivor-core.min.js";
write(manifest.out.module + ".map", JSON.stringify(mm));

// ---- CSS ----
function buildCss(files, outRel) {
  const cssSrc = files.map((f) => `/* ${f} */\n` + read(f)).join("\n");
  const css = esbuild.transformSync(cssSrc, { loader: "css", minify: true, legalComments: "none", charset: "utf8" });
  write(outRel, header + css.code);
}
buildCss(manifest.css, manifest.out.css);
for (const [name, g] of lazyGroups) buildCss(g.css, manifest.out.lazy[name].css);

// ---- build info ----
const size = (rel) => fs.statSync(path.join(root, rel)).size;
const srcBytes = (files) => files.reduce((n, f) => n + size(f), 0);
const info = {
  hash, esbuild: esbuild.version,
  js: { files: manifest.js.length, sourceBytes: srcBytes(manifest.js), builtBytes: size(manifest.out.js) },
  css: { files: manifest.css.length, sourceBytes: srcBytes(manifest.css), builtBytes: size(manifest.out.css) },
  lazy: Object.fromEntries(lazyGroups.map(([name, g]) => [name, {
    jsSourceBytes: srcBytes(g.js), jsBuiltBytes: size(manifest.out.lazy[name].js),
    cssSourceBytes: srcBytes(g.css), cssBuiltBytes: size(manifest.out.lazy[name].css),
    coreSourceBytes: size(manifest.module), coreBuiltBytes: size(manifest.out.module),
  }])),
};
write(manifest.out.info, JSON.stringify(info, null, 2) + "\n");
const sv = info.lazy.survivor;
console.log(`build ${hash}: main js ${info.js.sourceBytes} -> ${info.js.builtBytes}, css ${info.css.sourceBytes} -> ${info.css.builtBytes} | survivor (lazy) js ${sv.jsSourceBytes} -> ${sv.jsBuiltBytes}, css ${sv.cssSourceBytes} -> ${sv.cssBuiltBytes}, core -> ${sv.coreBuiltBytes}`);
